import boto3, json, os, time
from botocore.exceptions import ClientError
sqs=boto3.client("sqs")
def handler(event, context):
    authority=None
    if event.get("authority_probe"):
        try:
            if os.environ["KIND"] == "eventbridge":
                authority=boto3.client("events").put_events(Entries=[{"Source":"stackd.leo.authority","DetailType":"permission control","Detail":"{}","EventBusName":os.environ["DESTINATION"]}])
            else:
                authority=boto3.client("lambda").invoke(FunctionName=os.environ["DESTINATION"],InvocationType="DryRun")
                authority.pop("Payload",None)
        except ClientError as error:
            authority=error.response
    witness={"kind":"source_execution","label":event["label"],"event":event,"runtime_request_id":context.aws_request_id,"invoked_function_arn":context.invoked_function_arn,"runtime_time_ms":int(time.time()*1000),"authority_probe":authority}
    sqs.send_message(QueueUrl=os.environ["QUEUE_URL"],MessageBody=json.dumps(witness))
    if event.get("fail"):
        raise ValueError("native-outcome-failure:"+event["label"])
    return {"ok":True,"label":event["label"],"runtime_request_id":context.aws_request_id,"value":{"unicode":"λ","nil":None,"items":[1,False,"x"]}}

